  const selection = {};
  const knowledge = {};
  for (const line of m[1].split(/\r?\n/)) {
    const cells = line.trim().replace(/^\||\|$/g, '').split('|').map(c => c.trim());
    if (cells.length < 2) continue;
    const slot = cells[0].split(/\s+/)[0];
