  for (const dir of slotDirs) if (!(dir in SLOTS)) out.push(lib.finding(ERR, `.claude/capabilities/${dir}`, 'only the agreed capability slots may exist'));
  for (const [slot, model] of Object.entries(SLOTS)) {
